package com.onebytelabs.zlplay;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import com.onebytelabs.zlplay.audio.*;import java.lang.reflect.*;
public final class RoutingSmoke {
 static Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 static void call(Object o,String name,Class<?>[] types,Object...args){try{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}}
 static View find(View v,String name){if(v.getContentDescription()!=null&&name.contentEquals(v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=find(g.getChildAt(i),name);if(found!=null)return found;}}return null;}
 static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);}
 static void tap(View v,float x,float y){long now=SystemClock.uptimeMillis();MotionEvent d=MotionEvent.obtain(now,now,0,x,y,0),u=MotionEvent.obtain(now,now+35,1,x,y,0);v.dispatchTouchEvent(d);v.dispatchTouchEvent(u);d.recycle();u.recycle();}
 public static Bundle run(Instrumentation test)throws Exception{
 android.content.SharedPreferences prefs=test.getTargetContext().getSharedPreferences("mix",0);java.util.Map<String,?> saved=new java.util.HashMap<>(prefs.getAll());MainActivity screen=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).putExtra("com.onebytelabs.zlplay.SKIP_RESTORE_TEST",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{test.waitForIdleSync();for(int rate:new int[]{44100,48000}){DemoMixer mixer=new DemoMixer();mixer.setPad(true);try(AudioSession audio=new AudioSession(test.getTargetContext(),mixer,0,rate,2)){check(audio.start(),"Audio focus at "+rate);Thread.sleep(550);check(audio.error()==null&&audio.writtenFrames()>4096&&audio.blockRms()>.001,"Real AudioTrack at "+rate+" error="+audio.error()+" frames="+audio.writtenFrames()+" rms="+audio.blockRms()+" pad="+mixer.isPad());}}test.runOnMainSync(()->call(screen,"showMixer",new Class<?>[]{}));test.waitForIdleSync();DemoMixer mixer=(DemoMixer)get(screen,"mixer");Dialog dialog=(Dialog)get(screen,"mixerDialog");View root=dialog.getWindow().getDecorView();FaderSeekBar fader=(FaderSeekBar)find(root,screen.getString(R.string.volume,screen.getString(R.string.bass)));check(fader!=null,"Source fader");test.runOnMainSync(()->{fader.setProgress(35);float head=fader.getPaddingLeft()+(fader.getWidth()-fader.getPaddingLeft()-fader.getPaddingRight())*fader.getProgress()/(float)fader.getMax();tap(fader,head,fader.getHeight()/2f);tap(fader,head,fader.getHeight()/2f);});check(Math.abs(mixer.getGain(0)-1)<.001,"Double tap restores exactly 0 dB");check(find(root,screen.getString(R.string.pan,screen.getString(R.string.bass)))==null,"Pan slider removed");test.runOnMainSync(()->{dialog.dismiss();call(screen,"showSettings",new Class<?>[]{int.class},1);});test.waitForIdleSync();Dialog settings=(Dialog)get(screen,"settingsDialog");check(settings.isShowing(),"Working audio settings opens");test.runOnMainSync(settings::dismiss);Bundle b=new Bundle();b.putString("status","PASS: real stereo AudioTrack at 44.1/48 kHz, output settings, no pan sliders and thumb double-tap 0 dB");return b;}finally{test.runOnMainSync(screen::finish);android.content.SharedPreferences.Editor edit=prefs.edit().clear();for(var e:saved.entrySet()){Object v=e.getValue();if(v instanceof String)edit.putString(e.getKey(),(String)v);else if(v instanceof Boolean)edit.putBoolean(e.getKey(),(Boolean)v);else if(v instanceof Integer)edit.putInt(e.getKey(),(Integer)v);else if(v instanceof Float)edit.putFloat(e.getKey(),(Float)v);else if(v instanceof Long)edit.putLong(e.getKey(),(Long)v);}edit.commit();}}
}
